"삿포로 설정 #-#-#. toBase = [분, 수단]. 신치토세 국제선 터미널→JR역은 연결 통로·무빙워크 약 #분(공식 포르톰홀 안내) + 쾌속 에어포트 최단 #분(JR홋카이도 공식, 요금 #,#엔). 스스키노는 삿포로역 환승 #분+#분 추정. out/back = 비행기 시각 미입력 때 쓰는 가정값(앱에서 '가정'으로 표시): #/# 신규 에어프레미아 인천 #:#→신치토세 #:#(기사), 귀국편 #:# 출발은 기사 도착시각(#:#)이 시차 계산상 맞지 않아 도착은 비행시간 약 #시간 #분으로 가정": "札幌设置 #-#-#。toBase = [分钟, 方式]。新千岁机场国际线航站楼→JR站，连接通道·自动步道约#分钟(官方设施说明) + 快速Airport最短#分钟(JR北海道官方，票价#,#日元)。薄野按札幌站换乘#分钟+#分钟估算。out/back = 未填航班时间时使用的假设值(应用内标为“假设”)：#/# 新增 Air Premia 仁川 #:#→新千岁 #:#(报道)，回程航班 #:# 出发，报道中的到达时刻(#:#)与时差计算对不上，所以到达按飞行时间约#小时#分钟假设",
